WITH unpivoted AS (SELECT * FROM (SELECT id, category, cost, price FROM products) src UNPIVOT INCLUDE NULLS (value FOR metric IN (cost, price)) u) SELECT metric, CASE WHEN value >= 63 THEN 'HIGH' ELSE 'LOW' END AS value_tier, COUNT_IF(metric = 'cost') AS cost_events, MAX(value) FILTER (WHERE category = 'Grocery') AS grocery_max_value, SUM(CASE WHEN category = 'Sports' THEN value ELSE 0 END) AS sports_value, COUNT(DISTINCT id) AS distinct_ids FROM unpivoted GROUP BY CUBE (metric, CASE WHEN value >= 63 THEN 'HIGH' ELSE 'LOW' END) HAVING sports_value > 0 ORDER BY value_tier DESC
